// A story match replaces the player's team with a fixed squad.
// Every player is added to team 0 (the player's team) at level 1,
// numbered 1 to 11, then two of them swap positions.
InitBtl <- function ()
{
	CMND_BTL_SET_SHOES_AND_GLOVE(0, "ssa0001", "sga0001");
	CMND_BTL_ADD_MEMBER(0, "para_cp0001", 1, 1);
	CMND_BTL_ADD_MEMBER(0, "para_cp0002", 1, 2);
	CMND_BTL_ADD_MEMBER(0, "para_cp0003", 1, 3);
	CMND_BTL_ADD_MEMBER(0, "para_cp0004", 1, 4);
	// ... players 5 to 11 ...
	CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0001", 1);
	CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0003", 2);
};

// Give the opponent team (1) a high-level player in slot 10.
// At level 50 every Special Move it learns by level 50 is available.
CMND_BTL_ADD_MEMBER(1, "para_cp0010", 50, 10);
